effect.shader:
float gmHash2(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
float gmVnoise(vec2 p){
vec2 i = floor(p);
vec2 f = fract(p);
f = f * f * (3.0 - 2.0 * f);
float a = gmHash2(i);
float b = gmHash2(i + vec2(1.0, 0.0));
float c = gmHash2(i + vec2(0.0, 1.0));
float d = gmHash2(i + vec2(1.0, 1.0));
return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
void main(){
vec2 uv = acScreenNorm;
vec4 src = texture2DCv(inputImg.texture, uv);
float aspect = max(getTexSize(inputImg.size).x / max(getTexSize(inputImg.size).y, 1.0), 0.5);
vec2 fp = uv * vec2(fogScale, fogScale / aspect);
float t = acTime * fogSpeed;
float n1 = gmVnoise(fp + vec2(t * 0.30, -t * 0.12));
float n2 = gmVnoise(fp * 2.3 + vec2(-t * 0.5, t * 0.2) + n1 * 1.2);
float fog = n1 * 0.62 + n2 * 0.38;
fog = smoothstep(0.25, 0.95, fog);
float hb = mix(1.0, 1.0 - uv.y * 0.85, heightBias);
fog *= hb;
fog *= fogDensity;
vec3 col = src.rgb;
if (fogSoft > 0.01) {
vec2 px = 1.5 / getTexSize(inputImg.size);
vec3 softC = texture2DCv(inputImg.texture, uv + vec2(px.x, 0.0)).rgb
+ texture2DCv(inputImg.texture, uv - vec2(px.x, 0.0)).rgb
+ texture2DCv(inputImg.texture, uv + vec2(0.0, px.y)).rgb
+ texture2DCv(inputImg.texture, uv - vec2(0.0, px.y)).rgb;
softC *= 0.25;
col = mix(col, softC, fogSoft * fog);
}
col = mix(col, fogColor.rgb * (0.85 + 0.3 * fog), clamp(fog, 0.0, 1.0) * 0.85);
col = mix(col, col + fogColor.rgb * fogLift * fog, 1.0);
col = max(col, fogColor.rgb * fogLift * fog * 0.6);
gl_FragColor = vec4(mix(src.rgb, col, mixFog * 0.01) * src.a, src.a);
}
